package com.example.editor.textual.web;
import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import com.example.editor.textual.runtime.*;
@RestController
@RequestMapping("/api/textual-model-sessions")
public class TextualModelSessionController {
 private final TextualModelSessionService service;private final TextualQuickFixRuntimeService quickFixes;/** Descripción: Inicializa una instancia de TextualModelSessionController con sus dependencias y datos de entrada. Entradas: s: dato de entrada necesario para la operación; q: dato de entrada necesario para la operación. Salida: deja la instancia inicializada y lista para su uso. */ public TextualModelSessionController(TextualModelSessionService s,TextualQuickFixRuntimeService q){service=s;quickFixes=q;}
 /** Descripción: Crea o prepara el resultado de «create» dentro de TextualModelSessionController. Entradas: r: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ @PostMapping public ResponseEntity<TextualModelSession>create(@RequestBody CreateTextualModelSessionRequest r){var s=service.create(r);return ResponseEntity.ok().header(HttpHeaders.ETAG,s.etag()).body(s.document());}
 @GetMapping("/{id}")public ResponseEntity<TextualModelSession>find(@PathVariable String id){var s=service.find(id);return ResponseEntity.ok().header(HttpHeaders.ETAG,s.etag()).body(s.document());}
 @PostMapping("/{id}/parse")public ResponseEntity<TextualModelSession>parse(@PathVariable String id,@RequestHeader(value=HttpHeaders.IF_MATCH,required=false)String e,@RequestBody ParseTextualModelRequest r){var s=service.parse(id,r,e);return ResponseEntity.ok().header(HttpHeaders.ETAG,s.etag()).body(s.document());}
 @PostMapping("/{id}/save")public ResponseEntity<TextualModelSession>save(@PathVariable String id,@RequestHeader(value=HttpHeaders.IF_MATCH,required=false)String e){var s=service.save(id,e);return ResponseEntity.ok().header(HttpHeaders.ETAG,s.etag()).body(s.document());}
 @GetMapping("/{id}/semantic-at")public TextualModelSessionService.TextualSemanticLookupResult semanticAt(@PathVariable String id,@RequestParam String documentId,@RequestParam int line,@RequestParam int column){return service.semanticAt(id,documentId,line,column);}
 @PostMapping("/{id}/validation")public java.util.List<TextualValidationDiagnosticView>validate(@PathVariable String id){return quickFixes.validate(id);}
 @GetMapping("/{id}/validation/{diagnosticId}/quick-fixes")public java.util.List<com.example.editor.validation.quickfix.QuickFixDescriptor>quickFixes(@PathVariable String id,@PathVariable String diagnosticId){return quickFixes.resolve(id,diagnosticId);}
 @PostMapping("/{id}/validation/{diagnosticId}/quick-fixes/{actionId}/preview")public TextualQuickFixPreviewResult previewQuickFix(@PathVariable String id,@PathVariable String diagnosticId,@PathVariable String actionId,@RequestBody(required=false)com.example.editor.validation.quickfix.QuickFixExecutionRequest r){return quickFixes.preview(id,diagnosticId,actionId,r);}
 @PostMapping("/{id}/validation/{diagnosticId}/quick-fixes/{actionId}/apply")public ResponseEntity<TextualQuickFixApplicationResult>applyQuickFix(@PathVariable String id,@PathVariable String diagnosticId,@PathVariable String actionId,@RequestHeader(value=HttpHeaders.IF_MATCH,required=false)String e,@RequestBody(required=false)com.example.editor.validation.quickfix.QuickFixExecutionRequest r){var result=quickFixes.apply(id,diagnosticId,actionId,r,e);return ResponseEntity.ok().header(HttpHeaders.ETAG,result.etag()).body(result);}

}
